SELECT COALESCE(SUM(amount), 0)   AS totalAmount,
       COUNT(1)                   AS orderCount
FROM furniture_recharge_order
WHERE pay_status = 1
  AND pay_time >= #{monthStart}
  AND pay_time < #{monthEnd}

