SELECT COUNT(1)
FROM sys_user
WHERE del_flag = '0'
  AND create_time >= #{yesterdayStart}
  AND create_time < #{yesterdayEnd}

SELECT COUNT(1)
FROM sys_user
WHERE del_flag = '0'
  AND create_time >= #{dayStart}
  AND create_time < #{dayEnd}
